{
  "root": "main",
  "state": {
    "checklist": [
      {
        "issue": "Deposit return timing",
        "check": "When the deposit and statement were sent after move-out",
        "matters": "Late return can strengthen your claim"
      },
      {
        "issue": "Itemization",
        "check": "Whether deductions were listed clearly and specifically",
        "matters": "Vague charges are easier to dispute"
      },
      {
        "issue": "Wear and tear",
        "check": "Whether repainting/carpet cleaning were due to normal use only",
        "matters": "Normal wear is generally not chargeable"
      },
      {
        "issue": "Actual cost proof",
        "check": "Whether the landlord has receipts or estimates",
        "matters": "Deductions should match real costs"
      },
      {
        "issue": "Pre-existing condition",
        "check": "Whether the unit had similar wear at move-in",
        "matters": "Helps show the charges were not caused by you"
      },
      {
        "issue": "Notice and surrender date",
        "check": "Whether your notice and move-out date were documented",
        "matters": "Confirms the lease timeline and possession date"
      },
      {
        "issue": "Photos and inspections",
        "check": "Whether both sides documented condition",
        "matters": "Strong evidence for or against deductions"
      }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "intro", "rights_section", "docs_section", "checklist_table", "email_card", "actions_section"]
    },
    "title": { "type": "Text", "props": { "text": "California Security Deposit Review", "variant": "h1" }, "children": [] },
    "intro": { "type": "Text", "props": { "text": "Review your tenant rights regarding ordinary wear and tear, move-out notice, and deposit accounting requirements.", "variant": "body" }, "children": [] },
    "rights_section": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["rights_title", "rights_list"]
    },
    "rights_title": { "type": "Text", "props": { "text": "Tenant Rights Issues", "variant": "h2" }, "children": [] },
    "rights_list": {
      "type": "Text",
      "props": { "text": "Security deposit limits, ordinary wear and tear standards, itemized statement requirements, and statutory return deadlines.", "variant": "body" },
      "children": []
    },
    "docs_section": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["docs_title", "docs_list"]
    },
    "docs_title": { "type": "Text", "props": { "text": "Documents to Gather", "variant": "h2" }, "children": [] },
    "docs_list": {
      "type": "Text",
      "props": { "text": "Signed lease, proof of deposit, 30-day notice, move-in/out reports, landlord itemized statement, and repair receipts.", "variant": "body" },
      "children": []
    },
    "checklist_table": {
      "type": "Table",
      "props": {
        "domain": "status",
        "preferredPresentation": "cards",
        "columns": [
          { "key": "issue", "label": "Issue" },
          { "key": "check", "label": "What to Check" },
          { "key": "matters", "label": "Why It Matters" }
        ],
        "statePath": "/checklist"
      },
      "children": []
    },
    "email_card": {
      "type": "Card",
      "props": {},
      "children": ["email_title", "email_body"]
    },
    "email_title": { "type": "Text", "props": { "text": "Draft Request for Itemized Return", "variant": "h2" }, "children": [] },
    "email_body": { "type": "Text", "props": { "text": "I am writing regarding my security deposit. I believe the unit showed only normal wear and tear. Please provide a full itemized statement of all deductions, copies of receipts, and the remaining balance of my deposit within 10 business days.", "variant": "body" }, "children": [] },
    "actions_section": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "md" },
      "children": ["btn_courts", "btn_code"]
    },
    "btn_courts": { "type": "Button", "props": { "label": "California Courts", "on": { "press": { "action": "openUrl", "params": { "url": "https://selfhelp.courts.ca.gov/landlord-tenant/security-deposits" } } } }, "children": [] },
    "btn_code": { "type": "Button", "props": { "label": "CA Civil Code", "on": { "press": { "action": "openUrl", "params": { "url": "https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?sectionNum=1950.5.&lawCode=CIV" } } } }, "children": [] }
  }
}
